#!/usr/bin/env python3
"""Download the order listing and the customer records it refers to.

Everything the service returns is saved under DATA so the calculation can be
re-run without calling the service again. Retries, waits and token refreshes
are written to EVENTS.
"""
import http.client
import json
import os
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone
from email.utils import parsedate_to_datetime

BASE = "http://localhost:8080"
DATA = "/tmp/recon/data"
EVENTS = "/tmp/recon/events.log"
MAX_FAILURES = 25  # per request, before giving up loudly

token = None


def event(msg):
    stamp = datetime.now(timezone.utc).strftime("%H:%M:%S.%f")[:-3]
    with open(EVENTS, "a") as f:
        f.write(f"{stamp} {msg}\n")


def send(method, path, auth=True):
    headers = {"Authorization": f"Bearer {token}"} if auth else {}
    req = urllib.request.Request(BASE + path, method=method, headers=headers)
    try:
        with urllib.request.urlopen(req, timeout=30) as resp:
            return resp.status, resp.headers, resp.read()
    except urllib.error.HTTPError as err:
        return err.code, err.headers, err.read()


def wait_hint(headers, body):
    """Seconds the server asked us to wait, from a Retry-After header or a JSON field."""
    value = headers.get("Retry-After") if headers is not None else None
    if value:
        try:
            return float(value)
        except ValueError:
            try:
                when = parsedate_to_datetime(value)
                return max(0.0, (when - datetime.now(timezone.utc)).total_seconds())
            except (TypeError, ValueError):
                pass
    try:
        data = json.loads(body)
    except (TypeError, ValueError):
        return None
    if isinstance(data, dict):
        for key in ("retry_after", "retry_after_seconds", "wait_seconds"):
            if key in data:
                return float(data[key])
    return None


def retry(reason, hint, failures):
    """Log a failed attempt and wait before the next one."""
    if failures > MAX_FAILURES:
        raise RuntimeError(f"giving up: {reason}")
    wait = hint if hint is not None else min(2 ** failures, 30)
    event(f"{reason}; retrying in {wait:.1f}s (attempt {failures})")
    time.sleep(wait)


def call(method, path, auth=True):
    """Make a request and retry until the service gives a definitive answer.

    Returns (status, parsed_json). A 404 is returned rather than retried, because
    for /customers/{id} it means the id is unknown.
    """
    global token
    failures = 0
    while True:
        if auth and token is None:
            status, headers, body = send("POST", "/token", auth=False)
            if status == 200:
                token = json.loads(body)["token"]
                event("token issued")
                continue
            failures += 1
            retry(f"POST /token -> {status}", wait_hint(headers, body), failures)
            continue
        try:
            status, headers, body = send(method, path, auth)
        except (OSError, http.client.HTTPException) as err:
            failures += 1
            retry(f"{method} {path} network error {err!r}", None, failures)
            continue
        if status == 200:
            try:
                return 200, json.loads(body)
            except ValueError:
                failures += 1
                retry(f"{method} {path} returned non-JSON 200", None, failures)
                continue
        if status == 404 and path.startswith("/customers/"):
            event(f"404 for {path}: {body[:200]!r}")
            return 404, None
        if status in (401, 403):
            event(f"{status} on {method} {path}: {body[:200]!r}; discarding token")
            token = None
            failures += 1
            retry(f"{status} on {method} {path}", 0, failures)
            continue
        if status == 429:
            failures += 1
            retry(f"429 on {method} {path}: {body[:200]!r}", wait_hint(headers, body), failures)
            continue
        if status == 408 or status >= 500:
            failures += 1
            retry(f"{status} on {method} {path}: {body[:200]!r}", wait_hint(headers, body), failures)
            continue
        raise RuntimeError(f"unexpected {status} for {method} {path}: {body[:300]!r}")


def fetch_orders():
    pages = []
    seen = set()
    path = "/orders?page=1"
    while path is not None:
        if path in seen:
            raise RuntimeError(f"pagination loop at {path}")
        seen.add(path)
        _, data = call("GET", path)
        pages.append({"request": path, "response": data})
        event(
            f"orders {path}: {len(data['items'])} items, page={data['page']}, "
            f"total_pages={data['total_pages']}, next={data['next']!r}"
        )
        path = data["next"]
    return pages


def fetch_customers(ids):
    path = f"{DATA}/customers.json"
    customers = {}
    if os.path.exists(path):
        with open(path) as f:
            customers = json.load(f)
    for cid in sorted(ids):
        if cid in customers:
            continue
        status, data = call("GET", f"/customers/{cid}")
        customers[cid] = data if status == 200 else {"_status": status}
        with open(path, "w") as f:
            json.dump(customers, f, indent=1)
    return customers


def main():
    os.makedirs(DATA, exist_ok=True)
    pages = fetch_orders()
    with open(f"{DATA}/orders.json", "w") as f:
        json.dump(pages, f)
    ids = {item["customer_id"] for page in pages for item in page["response"]["items"]}
    customers = fetch_customers(ids)
    event(f"done: {len(pages)} pages, {len(ids)} distinct customers, {len(customers)} cached")
    print(f"pages={len(pages)} distinct_customers={len(ids)} cached={len(customers)}")


if __name__ == "__main__":
    main()

